# Builds a colony saved WITHOUT Ideology (the other four DLC stay active), for a suite whose scenario plays without that DLC (test-colony was saved with Ideology and throws on load without it).
#
#   scripts/Submit-PickleRun.ps1 ... -DepMap wsl-deps.sans-ideology-fixture.map -Filter pickletools-sans-ideology-fixture -Extra "-pickle-scenario-timeout=400"
!ludeon.rimworld.ideology
nelim.pickletools.newcolony   path:PickleTools/NewColony/Mod
nelim.pickletools.savesteps   path:PickleTools/SaveSteps/Mod
# The bundle committed under PickleTools/Mod is replaced by this shell, so the tools above are the only copy of their steps (see StandaloneBase).
nelim.pickletools   path:PickleTools/Tests/Pickle/StandaloneBase/Mod
